messageValues.message:
=Analyze this tech article and provide a comprehensive assessment:

Title: {{ $json.title }}
Content: {{ $json.contentSnippet || $json.description }}
Source: {{ $json.creator || 'Unknown' }}
Link: {{ $json.link }}

Provide a JSON response with:
{
  "engagement_score": (0-100),
  "sentiment": "positive/neutral/negative",
  "key_topics": ["topic1", "topic2", "topic3"],
  "target_audience": "description",
  "viral_potential": (0-100),
  "twitter_post": "optimized tweet with hashtags",
  "linkedin_post": "professional LinkedIn post",
  "youtube_script_outline": "3-5 bullet points for video",
  "summary": "2-sentence summary",
  "trending_score": (0-100)
}

parameters.jsCode:
// Parse OpenAI response and enhance with metadata (hardened + optimized)
const items = $input.all();
const enhancedContent = [];

// Build index of original aggregated items for O(1) lookups
const aggregatedItems = $("Content Aggregator").all();
const itemsByLink = new Map();
const itemsByTitle = new Map();
for (const aggItem of aggregatedItems) {
  const linkKey = typeof aggItem.json.link === "string" ? aggItem.json.link : undefined;
  const titleKey = typeof aggItem.json.title === "string" ? aggItem.json.title : undefined;
  if (linkKey) itemsByLink.set(linkKey, aggItem);
  if (titleKey) itemsByTitle.set(titleKey, aggItem);
}

for (const item of items) {
  let aiAnalysis;
  try {
    const aiResponse = item.json?.choices?.[0]?.message?.content;
    if (typeof aiResponse === "string") {
      aiAnalysis = JSON.parse(aiResponse);
    } else {
      throw new Error("Missing AI response");
    }
  } catch (error) {
    const safeTitle = String(item.json?.title ?? "").slice(0, 200);
    aiAnalysis = {
      engagement_score: 50,
      sentiment: "neutral",
      key_topics: ["technology"],
      target_audience: "tech professionals",
      viral_potential: 30,
      twitter_post: `🚀 ${safeTitle}... #tech #innovation`,
      linkedin_post: safeTitle ? `Industry insight: ${safeTitle}` : "Industry insight",
      youtube_script_outline: ["Introduction", "Key points", "Conclusion"],
      summary: "Interesting tech development worth sharing.",
      trending_score: 40
    };
  }

  const originalData = (item.json?.link && itemsByLink.get(item.json.link)) ||
                        (item.json?.title && itemsByTitle.get(item.json.title));

  if (!originalData) {
    continue;
  }

  const original = originalData.json || {};
  const description = original.contentSnippet || original.description || "";
  const title = typeof original.title === "string" ? original.title : "";
  const link = typeof original.link === "string" ? original.link : "";
  const source = original.creator || original.author || "Unknown";
  const publishedDate = original.pubDate || original.isoDate || null;

  enhancedContent.push({
    json: {
      title,
      link,
      source,
      published_date: publishedDate,
      description,
      ai_analysis: aiAnalysis,
      processed_at: new Date().toISOString(),
      quality_score: Number(aiAnalysis.engagement_score ?? 0),
      should_publish: Number(aiAnalysis.engagement_score ?? 0) >= 60,
      platforms_ready: {
        twitter: aiAnalysis.twitter_post,
        linkedin: aiAnalysis.linkedin_post,
        youtube_outline: aiAnalysis.youtube_script_outline
      },
      optimal_times: {
        twitter: new Date(Date.now() + 2 * 60 * 60 * 1000).toISOString(),
        linkedin: new Date(Date.now() + 8 * 60 * 60 * 1000).toISOString(),
        youtube: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString()
      }
    }
  });
}

// Sort by quality score
enhancedContent.sort((a, b) => (b.json.quality_score ?? 0) - (a.json.quality_score ?? 0));

return enhancedContent;
